insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-ek-133","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Standard cell EMF is obtained from standard reduction potentials as","options":["$E^\\circ_{\\mathrm{cell}} = E^\\circ_{\\mathrm{cathode}} - E^\\circ_{\\mathrm{anode}}$","$E^\\circ_{\\mathrm{cell}} = E^\\circ_{\\mathrm{anode}} - E^\\circ_{\\mathrm{cathode}}$","$E^\\circ_{\\mathrm{cell}} = E^\\circ_{\\mathrm{cathode}} \\times E^\\circ_{\\mathrm{anode}}$","$E^\\circ_{\\mathrm{cell}} = E^\\circ_{\\mathrm{cathode}} + 2E^\\circ_{\\mathrm{anode}}$"],"answer_index":0,"explanation":"Equivalently $E^\\circ_{\\mathrm{cell}} = E^\\circ_{\\mathrm{red}}(\\mathrm{oxidant}) + E^\\circ_{\\mathrm{ox}}(\\mathrm{reductant})$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-134","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In standard cell notation the electrode written on the left is the","options":["anode (oxidation half-cell)","cathode (reduction half-cell)","salt bridge","inert voltmeter terminal"],"answer_index":0,"explanation":"The IUPAC line diagram is anode | anodic electrolyte || cathodic electrolyte | cathode.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-135","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The line diagram of the Daniell cell is customarily written","options":["$\\mathrm{Zn}|\\mathrm{Zn^{2+}}||\\mathrm{Cu^{2+}}|\\mathrm{Cu}$","$\\mathrm{Cu}|\\mathrm{Cu^{2+}}||\\mathrm{Zn^{2+}}|\\mathrm{Zn}$","$\\mathrm{Zn}|\\mathrm{Cu}||\\mathrm{Zn^{2+}}|\\mathrm{Cu^{2+}}$","$\\mathrm{Pt}|\\mathrm{H_2}||\\mathrm{Zn^{2+}}|\\mathrm{Zn}$"],"answer_index":0,"explanation":"Zinc is oxidised (left) and Cu$^{2+}$ is reduced on copper (right).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-136","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A positive value of $E^\\circ_{\\mathrm{cell}}$ means that, under standard conditions, the cell reaction is","options":["spontaneous (product-favoured)","at equilibrium already","impossible in either direction","always endothermic"],"answer_index":0,"explanation":"$\\Delta G^\\circ = -nFE^\\circ$; a positive $E^\\circ$ makes $\\Delta G^\\circ$ negative, so the written reaction proceeds spontaneously.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-137","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In the external metallic circuit of a galvanic cell, electrons travel","options":["from the anode toward the cathode","from the cathode toward the anode","through the salt bridge as free electrons","in both directions at equal speed"],"answer_index":0,"explanation":"Oxidation releases electrons at the anode; they flow through the wire to the cathode, where reduction consumes them.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-138","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Standard electrode potential is an intensive quantity, so doubling the size of a half-cell","options":["leaves $E^\\circ$ unchanged","doubles $E^\\circ$","halves $E^\\circ$","makes $E^\\circ$ equal to $2F$"],"answer_index":0,"explanation":"Potential does not scale with the amount of electrode or electrolyte, unlike extensive $\\Delta G$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-139","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Among several half-cells, the strongest oxidising agent is the couple with the","options":["most positive standard reduction potential","most negative standard reduction potential","largest number of electrons in the half-reaction","smallest ionic charge"],"answer_index":0,"explanation":"A large positive $E^\\circ$ means the oxidised form is readily reduced, i.e. it is a strong oxidant.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-140","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A gas electrode such as the hydrogen electrode employs platinum chiefly as","options":["an inert surface on which the redox couple can exchange electrons","the species that is oxidised in place of hydrogen","a source of H$^+$ ions","the salt-bridge filling"],"answer_index":0,"explanation":"Pt is chemically inert here; it provides a conducting surface for $\\mathrm{H^+} / \\mathrm{H_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-141","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The EMF of a cell is the potential difference measured when","options":["no current is drawn (open-circuit condition)","a very large current is forced through the cell","the cell is short-circuited with a copper wire","the salt bridge is removed"],"answer_index":0,"explanation":"EMF is the reversible, zero-current voltage. A working current produces an IR drop, so the measured voltage is smaller.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-142","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If $E^\\circ(\\mathrm{Cu^{2+}/Cu}) = +0.34\\ \\mathrm{V}$ and $E^\\circ(\\mathrm{Zn^{2+}/Zn}) = -0.76\\ \\mathrm{V}$, $E^\\circ$ of the Daniell cell is","options":["$1.10\\ \\mathrm{V}$","$0.42\\ \\mathrm{V}$","$-1.10\\ \\mathrm{V}$","$0.34\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$E^\\circ_{\\mathrm{cell}} = 0.34 - (-0.76) = 1.10\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf"},{"id":"che-ek-143","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For the couples $\\mathrm{Ag^+/Ag}$ ($E^\\circ = +0.80\\ \\mathrm{V}$) and $\\mathrm{Zn^{2+}/Zn}$ ($E^\\circ = -0.76\\ \\mathrm{V}$), the anode of the spontaneous cell is","options":["zinc metal","silver metal","the Ag$^+$ solution","an inert platinum foil only"],"answer_index":0,"explanation":"The more negative couple is oxidised: Zn dissolves at the anode while Ag$^+$ is reduced.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf"},{"id":"che-ek-144","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The strongest reducing agent among Zn, Cu, Ag and H$_2$ (use $E^\\circ$: Zn $-0.76$, H $0.00$, Cu $+0.34$, Ag $+0.80\\ \\mathrm{V}$) is","options":["zinc","silver","copper","hydrogen gas"],"answer_index":0,"explanation":"The most negative reduction potential belongs to Zn$^{2+}$/Zn, so metallic zinc is the strongest reductant of the set.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf"},{"id":"che-ek-145","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The standard Gibbs energy change of a cell reaction is related to $E^\\circ$ by","options":["$\\Delta G^\\circ = -nFE^\\circ$","$\\Delta G^\\circ = nFE^\\circ$","$\\Delta G^\\circ = -E^\\circ / nF$","$\\Delta G^\\circ = nF / E^\\circ$"],"answer_index":0,"explanation":"Electrical work available from a reversible cell is $nFE$; that work equals $-\\Delta G$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf"},{"id":"che-ek-146","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The notation $\\mathrm{Pt}|\\mathrm{Fe^{2+},Fe^{3+}}||\\mathrm{Ag^+}|\\mathrm{Ag}$ implies that the cell reaction is","options":["$\\mathrm{Fe^{2+} + Ag^+ \\rightarrow Fe^{3+} + Ag}$","$\\mathrm{Fe^{3+} + Ag \\rightarrow Fe^{2+} + Ag^+}$","$\\mathrm{Fe^{2+} + Ag \\rightarrow Fe^{3+} + Ag^+}$","$\\mathrm{2Fe^{3+} + Ag^+ \\rightarrow 2Fe^{2+} + Ag}$"],"answer_index":0,"explanation":"Left-hand side is oxidised (Fe$^{2+} \\to$ Fe$^{3+}$) and right-hand side is reduced (Ag$^+ \\to$ Ag).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf"},{"id":"che-ek-147","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In an electrolytic cell, as opposed to a galvanic cell, the anode is","options":["the positive electrode, still the site of oxidation","the negative electrode, the site of reduction","always made of zinc","unnecessary if a salt bridge is present"],"answer_index":0,"explanation":"Oxidation is always anodic. An external source makes the electrolytic anode positive, whereas a galvanic anode is negative.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf"},{"id":"che-ek-148","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A large positive $E^\\circ_{\\mathrm{cell}}$ corresponds to","options":["a large equilibrium constant for the cell reaction","a vanishingly small $K$","$K$ exactly equal to 1","no relation at all to $K$"],"answer_index":0,"explanation":"$\\Delta G^\\circ = -RT\\ln K = -nFE^\\circ$, so a sizable positive $E^\\circ$ means $K \\gg 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf"},{"id":"che-ek-149","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For Zn–Cu with $E^\\circ = 1.10\\ \\mathrm{V}$ and $n = 2$, $\\Delta G^\\circ$ is nearest ($F = 96500\\ \\mathrm{C\\ mol^{-1}}$)","options":["$-212\\ \\mathrm{kJ\\ mol^{-1}}$","$-106\\ \\mathrm{kJ\\ mol^{-1}}$","$+212\\ \\mathrm{kJ\\ mol^{-1}}$","$-1.10\\ \\mathrm{kJ\\ mol^{-1}}$"],"answer_index":0,"explanation":"$\\Delta G^\\circ = -2 \\times 96500 \\times 1.10 = -212300\\ \\mathrm{J\\ mol^{-1}} \\approx -212\\ \\mathrm{kJ\\ mol^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"cells-emf"},{"id":"che-ek-150","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Couples: $\\mathrm{Ni^{2+}/Ni} = -0.25\\ \\mathrm{V}$, $\\mathrm{Ag^+/Ag} = +0.80\\ \\mathrm{V}$. The spontaneous standard cell and its $E^\\circ$ are","options":["Ni anode, Ag cathode; $1.05\\ \\mathrm{V}$","Ag anode, Ni cathode; $1.05\\ \\mathrm{V}$","Ni anode, Ag cathode; $0.55\\ \\mathrm{V}$","Ag anode, Ni cathode; $0.55\\ \\mathrm{V}$"],"answer_index":0,"explanation":"Ni is the better reductant, so it is the anode. $E^\\circ = 0.80 - (-0.25) = 1.05\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"cells-emf"},{"id":"che-ek-151","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The Nernst equation for a cell reaction with reaction quotient $Q$ is","options":["$E = E^\\circ - (RT/nF)\\ln Q$","$E = E^\\circ + (RT/nF)\\ln Q$","$E = E^\\circ - nF\\ln Q$","$E = (RT/nF)\\ln Q$ only"],"answer_index":0,"explanation":"The correction term subtracts a quantity that grows with $Q$, so the cell voltage falls as products accumulate.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-152","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"At $298\\ \\mathrm{K}$ the Nernst factor $2.303RT/F$ is close to","options":["$0.059\\ \\mathrm{V}$","$0.059\\ \\mathrm{mV}$","$8.314\\ \\mathrm{V}$","$96500\\ \\mathrm{V}$"],"answer_index":0,"explanation":"Intermediate problems therefore write $E = E^\\circ - (0.059/n)\\log Q$ at 25 °C.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-ek-133","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-134","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-135","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-136","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-137","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-138","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-139","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-140","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-141","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-142","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-143","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-144","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-145","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-146","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-147","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-148","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-149","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-150","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-151","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-152","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
